  const next = { ...profile, [modelKey(profile)]: value }, voices = voiceChoices(next, catalog);
  const previous = profile.voice?.split(":").pop();
  next.voice = voices.some((v3) => v3.id === profile.voice) ? profile.voice : voices.find((v3) => v3.id.endsWith(`:${previous}`))?.id || voices[0]?.id || "";
