// src/original/tts-local.js
var LOCAL_MODELS = Object.entries(tts_local_models_default.models).map(([id, value]) => ({ id, ...value }));
var LOCAL_DEFAULT_MODEL = "kokoro";
var LOCAL_DEFAULT_VOICE = tts_local_models_default.models.kokoro.defaultVoice;
function normalizeLocalProfile(profile = {}) {
  const model = tts_local_models_default.models[profile.model] ? profile.model : LOCAL_DEFAULT_MODEL;
  const voice = tts_local_models_default.models[model].voices.some((v3) => v3.id === profile.voice) ? profile.voice : tts_local_models_default.models[model].defaultVoice;
  return { ...profile, model, voice };
}
function localVoiceChoices(model, chinese = true) {
  return (tts_local_models_default.models[model]?.voices || []).map((v3) => {
    const language = !chinese ? v3.lang : !v3.lang.startsWith("zh") ? "\u82F1\u6587" : v3.gender === "male" ? "\u4E2D\u6587\u7537\u58F0" : v3.gender === "female" ? "\u4E2D\u6587\u5973\u58F0" : "";
    return {
      id: v3.id,
      label: [
        chinese ? v3.name : v3.nameEn,
        language,
        v3.recommended ? chinese ? "\u63A8\u8350" : "Recommended" : ""
      ].filter(Boolean).join(" \xB7 "),
      sourceName: `${tts_local_models_default.models[model].label} \xB7 ${v3.id}`,
      recommended: !!v3.recommended
    };
  });
}

// src/original/tts-local-ui.js
function action(host, icon, text4, run) {
  const button2 = host.createEl("button", { cls: "qbr-tts-button", attr: { type: "button" } });
  setIcon(button2, icon);
  button2.createSpan({ text: text4 });
  button2.addEventListener("click", run);
  return button2;
}
var LocalSpeechPanel = class {
  constructor(host, { manager, model, tx: tx2, errorText: errorText3, onReady, onState }) {
    Object.assign(this, { host, manager, model, tx: tx2, errorText: errorText3, onReady, onState });
    const selected = LOCAL_MODELS.find((x2) => x2.id === model);
    host.addClass("qbr-tts-local-panel");
    host.createDiv({ cls: "qbr-tts-choice-feedback", text: `${tx2("modelDownloadSize")} ${Math.ceil(selected?.bytes / 1024 ** 2)} MB \xB7 ${selected?.license || ""}` });
    this.status = host.createDiv({ cls: "qbr-tts-choice-feedback", attr: { role: "status", "aria-live": "polite" } });
    this.progress = host.createEl("progress", { attr: { max: "1" } });
    this.progress.hidden = true;
    const actions = host.createDiv("qbr-tts-local-actions");
    this.install = action(actions, "download", tx2("downloadUse"), async () => {
      try {
        await manager.install(model);
        if (!this.disposed) await onReady();
      } catch (error) {
        if (!this.disposed && error.name !== "AbortError") this.status.setText(errorText3(error));
      }
    });
    this.cancel = action(actions, "x", tx2("cancelDownload"), () => manager.cancelInstall(model));
    this.cancel.hidden = true;
    const details = host.createEl("details");
    details.createEl("summary", { text: tx2("localDetails") });
    details.createEl("p", { text: tx2("localStorage") });
    details.createEl("p", { text: tx2(model === "melo" ? "meloHelp" : "kokoroHelp") });
    details.createEl("a", { text: selected.label + " \xB7 " + selected.license, href: selected.source, attr: { target: "_blank", rel: "noopener" } });
    this.unsubscribe = manager.subscribe((id, state) => {
      if (id === model && !this.disposed) {
        this.refresh(state);
        onState?.(state);
      }
    });
    this.refresh(manager.snapshot(model));
    void manager.status(model).catch((error) => {
      if (!this.disposed) this.status.setText(errorText3(error));
    });
  }
  refresh(state) {
    const busy = ["runtime", "download", "downloaded", "environment", "extract", "installed", "verify", "cancelling"].includes(state.phase);
    const ready = state.phase === "ready";
    this.install.disabled = busy;
    this.install.hidden = ready;
    this.cancel.hidden = !busy;
    this.progress.hidden = !busy;
    this.cancel.disabled = state.phase === "cancelling";
    if (state.total) {
      this.progress.value = state.bytes / state.total;
    } else this.progress.removeAttribute("value");
    const progress = state.total ? ` \xB7 ${Math.floor(state.bytes / 1024 ** 2)} / ${Math.ceil(state.total / 1024 ** 2)} MB` : "";
    this.status.setText(state.phase === "error" ? this.errorText(state.error) : this.tx(`localPhase-${state.phase}`) + progress);
  }
  destroy() {
    this.disposed = true;
    this.unsubscribe?.();
  }
};

