    "ebook.retry": "\uB2E4\uC2DC \uC2DC\uB3C4",
    "ebook.error-code": "QM-\uC73C\uB85C \uC2DC\uC791\uD558\uB294 \uC804\uCCB4 \uCF54\uB4DC\uB97C \uD655\uC778\uD558\uC138\uC694.",
    "ebook.error-access": "\uAD8C\uD55C\uC774 \uB9CC\uB8CC\uB418\uAC70\uB098 \uC911\uC9C0\uB418\uC5C8\uAC70\uB098 \uB2E4\uC2DC \uD65C\uC131\uD654\uD574\uC57C \uD569\uB2C8\uB2E4. \uACF5\uAC1C \uC18C\uC2A4\uB294 \uACC4\uC18D \uC774\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
    "ebook.error-devices": "\uAE30\uAE30 \uC218 \uC81C\uD55C\uC5D0 \uB3C4\uB2EC\uD588\uC2B5\uB2C8\uB2E4. \uAD00\uB9AC\uC790\uC5D0\uAC8C \uC774\uC804 \uAE30\uAE30 \uD574\uC81C\uB97C \uC694\uCCAD\uD558\uC138\uC694.",
    "ebook.error-quota": "\uC624\uB298 \uB2E4\uC6B4\uB85C\uB4DC \uD55C\uB3C4\uB97C \uC18C\uC9C4\uD588\uC2B5\uB2C8\uB2E4. \uB0B4\uC77C \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.",
    "ebook.error-save": "\uB85C\uADF8\uC778 \uC815\uBCF4\uB97C \uC800\uC7A5\uD558\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4. \uB85C\uCEEC \uC800\uC7A5\uC18C\uB97C \uD655\uC778\uD558\uACE0 \uB2E4\uC2DC \uD65C\uC131\uD654\uD558\uC138\uC694.",
    "ebook.error-network": "\uC5F0\uACB0 \uC2E4\uD328 \uB610\uB294 \uC11C\uBE44\uC2A4 \uC0AC\uC6A9\uB7C9\uC774 \uB9CE\uC2B5\uB2C8\uB2E4. \uB098\uC911\uC5D0 \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694. \uACF5\uAC1C \uC18C\uC2A4\uB294 \uACC4\uC18D \uC774\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
    "ebook.error-download": "\uB2E4\uC6B4\uB85C\uB4DC\uD558\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4. \uD69F\uC218\uB294 \uBCF5\uAD6C\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.",
    "ebook.error-file": "\uD30C\uC77C \uAC80\uC99D\uC5D0 \uC2E4\uD328\uD558\uC5EC \uAC00\uC838\uC624\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. \uB2E4\uC2DC \uB2E4\uC6B4\uB85C\uB4DC\uD558\uC138\uC694.",
    "ebook.error-busy": "\uC9C4\uD589 \uC911\uC778 \uB2E4\uC6B4\uB85C\uB4DC\uAC00 \uB05D\uB0A0 \uB54C\uAE4C\uC9C0 \uAE30\uB2E4\uB9AC\uC138\uC694.",
    "ebook.error-pending": "\uB2E4\uC6B4\uB85C\uB4DC\uAC00 \uC9C4\uD589 \uC911\uC785\uB2C8\uB2E4. Qiaomu \uC11C\uC7AC\uB97C \uB2E4\uC2DC \uC5F4\uC5B4 \uAC00\uC838\uC624\uAE30\uB97C \uACC4\uC18D\uD558\uC138\uC694.",
    "ebook.error-expired": "\uACB0\uACFC \uB610\uB294 \uD30C\uC77C\uC774 \uB9CC\uB8CC\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uB2E4\uC2DC \uAC80\uC0C9\uD558\uC138\uC694.",
