var languages2 = ["zh", "en", "ru", "ja", "es", "fr", "de", "ko", "pt"];
var messages2 = {
  "kindle.setup-intro": ["USB \u53EA\u7528\u4E8E\u9996\u6B21\u6388\u6743\uFF0C\u8BA9 Kindle \u8BA4\u5F97\u8FD9\u53F0\u7535\u8111\u3002\u4EE5\u540E\u4F20\u4E66\u90FD\u8D70 Wi-Fi\uFF0C\u65E0\u9700\u63D2\u7EBF\u3002", "USB is only needed once to authorize this computer. After that, books are sent over Wi-Fi without a cable.", "USB \u043D\u0443\u0436\u0435\u043D \u043E\u0434\u0438\u043D \u0440\u0430\u0437 \u0434\u043B\u044F \u0430\u0432\u0442\u043E\u0440\u0438\u0437\u0430\u0446\u0438\u0438 \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0430. \u0417\u0430\u0442\u0435\u043C \u043A\u043D\u0438\u0433\u0438 \u043F\u0435\u0440\u0435\u0434\u0430\u044E\u0442\u0441\u044F \u043F\u043E Wi-Fi \u0431\u0435\u0437 \u043A\u0430\u0431\u0435\u043B\u044F.", "USB\u306F\u3053\u306E\u30D1\u30BD\u30B3\u30F3\u306E\u521D\u56DE\u8A8D\u8A3C\u3060\u3051\u306B\u5FC5\u8981\u3067\u3059\u3002\u305D\u306E\u5F8C\u306F\u30B1\u30FC\u30D6\u30EB\u306A\u3057\u3067Wi-Fi\u8EE2\u9001\u3067\u304D\u307E\u3059\u3002", "El USB solo se necesita una vez para autorizar este ordenador. Despu\xE9s, env\xEDa libros por Wi-Fi sin cable.", "L\u2019USB sert une seule fois \xE0 autoriser cet ordinateur. Ensuite, envoyez les livres en Wi-Fi, sans c\xE2ble.", "USB wird nur einmal zur Autorisierung dieses Computers ben\xF6tigt. Danach werden B\xFCcher kabellos per WLAN gesendet.", "USB\uB294 \uCC98\uC74C\uC5D0 \uC774 \uCEF4\uD4E8\uD130\uB97C \uC778\uC99D\uD560 \uB54C\uB9CC \uD544\uC694\uD569\uB2C8\uB2E4. \uC774\uD6C4\uC5D0\uB294 \uCF00\uC774\uBE14 \uC5C6\uC774 Wi-Fi\uB85C \uCC45\uC744 \uBCF4\uB0C5\uB2C8\uB2E4.", "O USB s\xF3 \xE9 necess\xE1rio uma vez para autorizar este computador. Depois, envie livros por Wi-Fi, sem cabo."],
  "kindle.ready-intro": ["\u8FD9\u53F0\u7535\u8111\u5DF2\u83B7\u6388\u6743\uFF0C\u53EF\u4EE5\u76F4\u63A5\u901A\u8FC7 Wi-Fi \u4F20\u4E66\uFF0C\u4E0D\u5FC5\u8FDE\u63A5 USB\u3002", "This computer is authorized. Send books over Wi-Fi; no USB cable is needed.", "\u041A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440 \u0430\u0432\u0442\u043E\u0440\u0438\u0437\u043E\u0432\u0430\u043D. \u041F\u0435\u0440\u0435\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u043A\u043D\u0438\u0433\u0438 \u043F\u043E Wi-Fi \u0431\u0435\u0437 USB.", "\u3053\u306E\u30D1\u30BD\u30B3\u30F3\u306F\u8A8D\u8A3C\u6E08\u307F\u3067\u3059\u3002USB\u306A\u3057\u3067Wi-Fi\u8EE2\u9001\u3067\u304D\u307E\u3059\u3002", "Este ordenador est\xE1 autorizado. Env\xEDa libros por Wi-Fi, sin USB.", "Cet ordinateur est autoris\xE9. Envoyez les livres en Wi-Fi, sans USB.", "Dieser Computer ist autorisiert. B\xFCcher k\xF6nnen ohne USB per WLAN gesendet werden.", "\uC774 \uCEF4\uD4E8\uD130\uB294 \uC778\uC99D\uB418\uC5C8\uC2B5\uB2C8\uB2E4. USB \uC5C6\uC774 Wi-Fi\uB85C \uCC45\uC744 \uBCF4\uB0B4\uC138\uC694.", "Este computador est\xE1 autorizado. Envie livros por Wi-Fi, sem USB."],
  "kindle.step-usb": ["\u9996\u6B21\u6388\u6743\uFF0C\u53EA\u9700\u4E00\u6B21", "One-time authorization", "\u0410\u0432\u0442\u043E\u0440\u0438\u0437\u0430\u0446\u0438\u044F \u043E\u0434\u0438\u043D \u0440\u0430\u0437", "\u521D\u56DE\u3060\u3051\u306E\u8A8D\u8A3C", "Autorizaci\xF3n inicial", "Autorisation initiale", "Einmalige Autorisierung", "\uCC98\uC74C \uD55C \uBC88\uB9CC \uC778\uC99D", "Autoriza\xE7\xE3o inicial"],
  "kindle.usb-complete": ["\u5DF2\u6388\u6743\u8FD9\u53F0\u7535\u8111", "Computer authorized", "\u041A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440 \u0430\u0432\u0442\u043E\u0440\u0438\u0437\u043E\u0432\u0430\u043D", "\u30D1\u30BD\u30B3\u30F3\u306F\u8A8D\u8A3C\u6E08\u307F", "Ordenador autorizado", "Ordinateur autoris\xE9", "Computer autorisiert", "\uCEF4\uD4E8\uD130 \uC778\uC99D \uC644\uB8CC", "Computador autorizado"],
  "kindle.usb-description": ["\u9000\u51FA KOReader\uFF0C\u7528 USB \u8FDE\u63A5\u7535\u8111\uFF0C\u7136\u540E\u70B9\u51FB\u4E0B\u65B9\u6309\u94AE\u3002", "Exit KOReader, connect Kindle to this computer by USB, then click below.", "\u0417\u0430\u043A\u0440\u043E\u0439\u0442\u0435 KOReader, \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0438\u0442\u0435 Kindle \u043F\u043E USB \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u043A\u043D\u043E\u043F\u043A\u0443 \u043D\u0438\u0436\u0435.", "KOReader\u3092\u7D42\u4E86\u3057\u3001Kindle\u3092USB\u3067\u63A5\u7D9A\u3057\u3066\u3001\u4E0B\u306E\u30DC\u30BF\u30F3\u3092\u62BC\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "Cierra KOReader, conecta Kindle por USB y pulsa el bot\xF3n de abajo.", "Fermez KOReader, branchez Kindle en USB, puis cliquez ci-dessous.", "KOReader beenden, Kindle per USB verbinden und unten klicken.", "KOReader\uB97C \uC885\uB8CC\uD558\uACE0 Kindle\uC744 USB\uB85C \uC5F0\uACB0\uD55C \uB4A4 \uC544\uB798 \uBC84\uD2BC\uC744 \uB204\uB974\uC138\uC694.", "Feche o KOReader, conecte o Kindle por USB e clique abaixo."],
  "kindle.pair": ["\u6388\u6743\u8FD9\u53F0\u7535\u8111", "Authorize this computer", "\u0410\u0432\u0442\u043E\u0440\u0438\u0437\u043E\u0432\u0430\u0442\u044C \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440", "\u3053\u306E\u30D1\u30BD\u30B3\u30F3\u3092\u8A8D\u8A3C", "Autorizar este ordenador", "Autoriser cet ordinateur", "Diesen Computer autorisieren", "\uC774 \uCEF4\uD4E8\uD130 \uC778\uC99D", "Autorizar este computador"],
  "kindle.repair": ["\u91CD\u65B0\u6388\u6743", "Authorize again", "\u0410\u0432\u0442\u043E\u0440\u0438\u0437\u043E\u0432\u0430\u0442\u044C \u0441\u043D\u043E\u0432\u0430", "\u518D\u8A8D\u8A3C", "Volver a autorizar", "Autoriser \xE0 nouveau", "Erneut autorisieren", "\uB2E4\uC2DC \uC778\uC99D", "Autorizar novamente"],
  "kindle.step-wifi": ["Wi-Fi \u4F20\u4E66", "Send over Wi-Fi", "\u041F\u0435\u0440\u0435\u0434\u0430\u0447\u0430 \u043F\u043E Wi-Fi", "Wi-Fi\u3067\u672C\u3092\u8EE2\u9001", "Enviar por Wi-Fi", "Envoi par Wi-Fi", "Per WLAN senden", "Wi-Fi\uB85C \uCC45 \uBCF4\uB0B4\uAE30", "Enviar por Wi-Fi"],
  "kindle.address-help": ["\u6253\u5F00 KOReader\uFF0C\u8BA9 Kindle \u548C\u7535\u8111\u8FDE\u63A5\u540C\u4E00 Wi-Fi\uFF0C\u518D\u70B9\u51FB\u300C\u67E5\u627E Kindle\u300D\u3002", "Open KOReader, connect both devices to the same Wi-Fi, then select Find Kindle.", "\u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 KOReader, \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u043E\u0431\u0430 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430 \u043A \u043E\u0434\u043D\u043E\u0439 \u0441\u0435\u0442\u0438 Wi-Fi \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \xAB\u041D\u0430\u0439\u0442\u0438 Kindle\xBB.", "KOReader\u3092\u958B\u304D\u3001\u4E21\u65B9\u3092\u540C\u3058Wi-Fi\u306B\u63A5\u7D9A\u3057\u3066\u300CKindle\u3092\u63A2\u3059\u300D\u3092\u62BC\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "Abre KOReader, conecta ambos dispositivos a la misma Wi-Fi y pulsa Buscar Kindle.", "Ouvrez KOReader, connectez les deux appareils au m\xEAme Wi-Fi, puis cliquez sur Trouver Kindle.", "KOReader \xF6ffnen, beide Ger\xE4te mit demselben WLAN verbinden und Kindle suchen w\xE4hlen.", "KOReader\uB97C \uC5F4\uACE0 \uB450 \uAE30\uAE30\uB97C \uAC19\uC740 Wi-Fi\uC5D0 \uC5F0\uACB0\uD55C \uB4A4 Kindle \uCC3E\uAE30\uB97C \uB204\uB974\uC138\uC694.", "Abra o KOReader, conecte os dois dispositivos \xE0 mesma rede Wi-Fi e selecione Buscar Kindle."],
  "kindle.usb-done": ["\u6388\u6743\u5B8C\u6210\u3002\u5B89\u5168\u5F39\u51FA\u5E76\u62D4\u4E0B USB\uFF0C\u6253\u5F00 KOReader \u540E\u5373\u53EF\u901A\u8FC7 Wi-Fi \u4F20\u4E66\u3002", "Authorized. Safely eject and unplug USB, then open KOReader to send books over Wi-Fi.", "\u0413\u043E\u0442\u043E\u0432\u043E. \u0411\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u043E \u0438\u0437\u0432\u043B\u0435\u043A\u0438\u0442\u0435 Kindle, \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u0435 USB \u0438 \u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 KOReader \u0434\u043B\u044F \u043F\u0435\u0440\u0435\u0434\u0430\u0447\u0438 \u043F\u043E Wi-Fi.", "\u8A8D\u8A3C\u5B8C\u4E86\u3002\u5B89\u5168\u306B\u53D6\u308A\u5916\u3057\u3066USB\u3092\u629C\u304D\u3001KOReader\u3092\u958B\u304F\u3068Wi-Fi\u8EE2\u9001\u3067\u304D\u307E\u3059\u3002", "Autorizado. Expulsa Kindle, desconecta el USB y abre KOReader para enviar por Wi-Fi.", "Autoris\xE9. \xC9jectez Kindle, d\xE9branchez l\u2019USB et ouvrez KOReader pour envoyer en Wi-Fi.", "Autorisiert. Kindle sicher auswerfen, USB trennen und KOReader f\xFCr WLAN-\xDCbertragungen \xF6ffnen.", "\uC778\uC99D \uC644\uB8CC. Kindle\uC744 \uC548\uC804\uD558\uAC8C \uAEBC\uB0B4 USB\uB97C \uBD84\uB9AC\uD558\uACE0 KOReader\uB97C \uC5F4\uBA74 Wi-Fi\uB85C \uBCF4\uB0BC \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "Autorizado. Ejete o Kindle, desconecte o USB e abra o KOReader para enviar por Wi-Fi."],
  "kindle.setup-update": ["\u9996\u6B21\u8FDE\u63A5\u4F1A\u8BF4\u660E USB \u4EC5\u7528\u4E8E\u4E00\u6B21\u6388\u6743\uFF1B\u5DF2\u6388\u6743\u540E\u76F4\u63A5\u663E\u793A Wi-Fi \u4F20\u4E66\u3002", "Kindle setup now explains one-time USB authorization and shows Wi-Fi delivery after authorization.", "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430 \u043E\u0431\u044A\u044F\u0441\u043D\u044F\u0435\u0442 \u0440\u0430\u0437\u043E\u0432\u0443\u044E USB-\u0430\u0432\u0442\u043E\u0440\u0438\u0437\u0430\u0446\u0438\u044E \u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u043F\u0435\u0440\u0435\u0434\u0430\u0447\u0443 \u043F\u043E Wi-Fi.", "\u521D\u56DE\u306EUSB\u8A8D\u8A3C\u3068\u3001\u305D\u306E\u5F8C\u306EWi-Fi\u8EE2\u9001\u3092\u308F\u304B\u308A\u3084\u3059\u304F\u6848\u5185\u3057\u307E\u3059\u3002", "La configuraci\xF3n explica la autorizaci\xF3n USB inicial y el env\xEDo posterior por Wi-Fi.", "La configuration explique l\u2019autorisation USB initiale, puis l\u2019envoi par Wi-Fi.", "Die Einrichtung erkl\xE4rt die einmalige USB-Autorisierung und anschlie\xDFende WLAN-\xDCbertragung.", "\uCC98\uC74C \uD55C \uBC88\uC758 USB \uC778\uC99D\uACFC \uC774\uD6C4 Wi-Fi \uC804\uC1A1\uC744 \uBA85\uD655\uD788 \uC548\uB0B4\uD569\uB2C8\uB2E4.", "A configura\xE7\xE3o explica a autoriza\xE7\xE3o USB inicial e o envio posterior por Wi-Fi."]
};
var KINDLE_SETUP_TEXT = Object.fromEntries(languages2.map((language, i2) => [
  language,
  Object.fromEntries(Object.entries(messages2).map(([key, values]) => [key, values[i2]]))
]));

