  "starter-books-failed": "\u672A\u80FD\u51C6\u5907\u793A\u4F8B\u4E66\u3002\u8BF7\u68C0\u67E5\u6587\u4EF6\u5939\u6743\u9650\uFF0C\u7136\u540E\u91CD\u8BD5\u3002",
  "translate-source-to-chinese": "\u7FFB\u8BD1\u6210\u4E2D\u6587",
  "translate-source-to-chinese-prompt": "\u8BF7\u5C06\u5F53\u524D\u5F15\u7528\u7684\u539F\u6587\u7FFB\u8BD1\u6210\u81EA\u7136\u3001\u51C6\u786E\u7684\u4E2D\u6587\u3002\u4FDD\u7559\u6BB5\u843D\u7ED3\u6784\u3001\u4E13\u6709\u540D\u8BCD\u548C\u539F\u610F\uFF0C\u76F4\u63A5\u7ED9\u51FA\u8BD1\u6587\uFF0C\u4E0D\u6DFB\u52A0\u89E3\u91CA\u3002",
  "text-and-background": "\u6587\u5B57\u4E0E\u80CC\u666F",
