  "restore-defaults": "\uAE30\uBCF8\uAC12 \uBCF5\uC6D0",
  "enter-both-a-name-and-prompt-text": "\uC774\uB984\uACFC \uD504\uB86C\uD504\uD2B8 \uD14D\uC2A4\uD2B8\uB97C \uBAA8\uB450 \uC785\uB825\uD558\uC138\uC694.",
  "quick-prompts-saved": "\uBE60\uB978 \uD504\uB86C\uD504\uD2B8\uAC00 \uC800\uC7A5\uB418\uC5C8\uC2B5\uB2C8\uB2E4",
  "manage-quick-prompts-2": "\uBE60\uB978 \uD504\uB86C\uD504\uD2B8 \uAD00\uB9AC",
  "choose-a-quick-prompt-or-write-your-own": "\uBE60\uB978 \uD504\uB86C\uD504\uD2B8\uB97C \uC120\uD0DD\uD558\uAC70\uB098 \uC9C1\uC811 \uC791\uC131\uD558\uC138\uC694.",
  "add-quick-prompts-from-the-settings-icon-above": "\uC704\uC758 \uC124\uC815 \uC544\uC774\uCF58\uC5D0\uC11C \uBE60\uB978 \uD504\uB86C\uD504\uD2B8\uB97C \uCD94\uAC00\uD558\uC138\uC694.",
  "open-the-note-0-in-a-new-tab-next-time-the-excerpt-will-be-added": "\uB178\uD2B8 \xAB{0}\xBB\uC744(\uB97C) \uC0C8 \uD0ED\uC5D0\uC11C \uC5EC\uC2DC\uACA0\uC2B5\uB2C8\uAE4C? \uB2E4\uC74C\uBD80\uD130\uB294 \uBC1C\uCDCC\uBB38\uC774 \uBB3B\uC9C0 \uC54A\uACE0 \uCD94\uAC00\uB429\uB2C8\uB2E4.",
  "not-now": "\uC9C0\uAE08\uC740 \uC548 \uD568",
  "quick-prompts-2": "\uBE60\uB978 \uD504\uB86C\uD504\uD2B8",
  "0-buttons-in-the-ai-dialog-rename-them-edit-the-full-prompts-add": "AI \uB300\uD654 \uC0C1\uC790\uC758 {0} \uBC84\uD2BC. \uC774\uB984\uC744 \uBC14\uAFB8\uAC70\uB098, \uC804\uCCB4 \uD504\uB86C\uD504\uD2B8\uB97C \uD3B8\uC9D1\uD558\uAC70\uB098, \uC9C1\uC811 \uCD94\uAC00\uD558\uAC70\uB098, \uD544\uC694 \uC5C6\uB294 \uAC83\uC744 \uC81C\uAC70\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
  "manage-2": "\uAD00\uB9AC",
  "after-appending-an-excerpt-the-reader-asks-whether-to-open-the-r": "\uBC1C\uCDCC\uBB38\uC744 \uCD94\uAC00\uD55C \uD6C4 \uB9AC\uB354\uB294 \uC77D\uAE30 \uB178\uD2B8\uB97C \uC5F4\uC9C0 \uD55C \uBC88\uB9CC \uBB3B\uACE0 \uC774\uD6C4 \uC77D\uAE30\uB97C \uBC29\uD574\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
  "ai-quick-prompts-can-now-be-added-edited-deleted-and-restored-to": "AI \uBE60\uB978 \uD504\uB86C\uD504\uD2B8\uB97C \uC774\uC81C \uCD94\uAC00, \uD3B8\uC9D1, \uC0AD\uC81C \uBC0F \uAE30\uBCF8\uAC12\uC73C\uB85C \uBCF5\uC6D0\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.",
  "the-ai-dialog-now-links-directly-to-prompt-settings-and-includes": "AI \uB300\uD654 \uC0C1\uC790\uAC00 \uC774\uC81C \uD504\uB86C\uD504\uD2B8 \uC124\uC815\uC5D0 \uC9C1\uC811 \uC5F0\uACB0\uB418\uBA70 \uC77C\uC0C1\uC801\uC778 \uC77D\uAE30\uB97C \uC704\uD574 \uC124\uACC4\uB41C 6\uAC00\uC9C0 \uC9C8\uBB38\uC774 \uD3EC\uD568\uB429\uB2C8\uB2E4.",
  "each-cli-remembers-its-own-model-leave-empty-for-that-cli-s-defa": "\uAC01 CLI\uB294 \uC790\uCCB4 \uBAA8\uB378\uC744 \uAE30\uC5B5\uD569\uB2C8\uB2E4. \uD574\uB2F9 CLI\uC758 \uAE30\uBCF8\uAC12\uC744 \uC0AC\uC6A9\uD558\uB824\uBA74 \uBE44\uC6CC \uB450\uAC70\uB098, \uB85C\uCEEC \uC124\uCE58\uC5D0\uC11C \uC9C0\uC6D0\uD558\uB294 \uBAA8\uB378 ID\uB97C \uC785\uB825\uD558\uC138\uC694.",
  "model-default": "\uBAA8\uB378 \uAE30\uBCF8\uAC12",
  "minimal": "\uCD5C\uC18C",
  "low": "\uB0AE\uC74C",
  "medium": "\uC911\uAC04",
  "high": "\uB192\uC74C",
  "extra-high": "\uB9E4\uC6B0 \uB192\uC74C",
  "maximum": "\uCD5C\uB300",
  "reasoning-effort": "\uCD94\uB860 \uB178\uB825",
  "clis-do-not-share-one-universal-thinking-switch-choose-low-for-f": "CLI\uB294 \uBCF4\uD3B8\uC801\uC778 \uC0AC\uACE0 \uC2A4\uC704\uCE58\uB97C \uACF5\uC720\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. \uB354 \uBE60\uB978 \uC751\uB2F5\uC744 \uC6D0\uD558\uBA74 \uB0AE\uC74C\uC744 \uC120\uD0DD\uD558\uACE0 \uC5B4\uB824\uC6B4 \uAD6C\uC808\uC5D0\uC11C\uB294 \uB192\uC774\uC138\uC694. \uC9C0\uC6D0\uB418\uC9C0 \uC54A\uB294 \uC218\uC900\uC740 \uC228\uACA8\uC9D1\uB2C8\uB2E4.",
  "the-reader-runs-0-in-an-isolated-temporary-directory-and-denies": "\uB9AC\uB354\uB294 {0}\uC744 \uACA9\uB9AC\uB41C \uC784\uC2DC \uB514\uB809\uD130\uB9AC\uC5D0\uC11C \uC2E4\uD589\uD558\uACE0 \uB3C4\uAD6C, \uD30C\uC77C, \uD130\uBBF8\uB110 \uAD8C\uD55C\uC744 \uAC70\uBD80\uD569\uB2C8\uB2E4. \uAC01 \uCC44\uD305\uC740 ACP \uC138\uC158\uC744 \uC7AC\uC0AC\uC6A9\uD569\uB2C8\uB2E4. \uCCAB \uBC88\uC9F8 \uD134\uC740 \uCCA8\uBD80\uD55C \uC77D\uAE30 \uCEE8\uD14D\uC2A4\uD2B8\uB97C \uBCF4\uB0B4\uACE0, \uD6C4\uC18D \uD134\uC740 \uC0C8 \uC9C8\uBB38\uB9CC \uBCF4\uB0C5\uB2C8\uB2E4. PDF \uD14D\uC2A4\uD2B8, \uD398\uC774\uC9C0 \uB610\uB294 \uC120\uD0DD \uC601\uC5ED, \uCC45 \uC81C\uBAA9, \uC9C8\uBB38\uC740 AI\uB97C \uC801\uADF9\uC801\uC73C\uB85C \uC0AC\uC6A9\uD560 \uB54C\uB9CC \uC804\uC1A1\uB429\uB2C8\uB2E4.",
  "these-controls-stay-in-sync-with-reading-settings-inside-the-rea": "\uC774 \uCEE8\uD2B8\uB864\uC740 \uB9AC\uB354 \uB0B4 \uC77D\uAE30 \uC124\uC815\uACFC \uB3D9\uAE30\uD654\uB429\uB2C8\uB2E4. \uD398\uC774\uC9C0\uB97C \uBCC0\uACBD\uD558\uC9C0\uB9CC \uB3C4\uAD6C \uBAA8\uC74C\uC740 \uACC4\uC18D Obsidian\uC744 \uB530\uB985\uB2C8\uB2E4.",
  "reading-appearance": "\uC77D\uAE30 \uBAA8\uC591",
  "theme-2": "\uD14C\uB9C8",
  "choose-a-page-background-for-your-current-environment": "\uD604\uC7AC \uD658\uACBD\uC5D0 \uB9DE\uB294 \uD398\uC774\uC9C0 \uBC30\uACBD\uC744 \uC120\uD0DD\uD558\uC138\uC694.",
  "body-font": "\uBCF8\uBB38 \uAE00\uAF34",
  "used-for-the-book-text-chinese-and-english-font-names-keep-their": "\uCC45 \uBCF8\uBB38\uC5D0 \uC0AC\uC6A9\uB429\uB2C8\uB2E4. \uC911\uAD6D\uC5B4\uC640 \uC601\uC5B4 \uAE00\uAF34 \uC774\uB984\uC740 \uC6D0\uB798 \uC774\uB984\uC744 \uC720\uC9C0\uD569\uB2C8\uB2E4.",
  "font-size-2": "\uAE00\uAF34 \uD06C\uAE30",
  "the-book-text-size-synced-with-the-in-reader-control": "\uCC45 \uBCF8\uBB38 \uD06C\uAE30, \uB9AC\uB354 \uB0B4 \uCEE8\uD2B8\uB864\uACFC \uB3D9\uAE30\uD654\uB429\uB2C8\uB2E4.",
  "line-spacing-2": "\uC904 \uAC04\uACA9",
  "long-form-chinese-text-is-usually-most-comfortable-at-1-6-1-8": "\uAE34 \uC911\uAD6D\uC5B4 \uD14D\uC2A4\uD2B8\uB294 \uBCF4\uD1B5 1.6\u20131.8\uC5D0\uC11C \uAC00\uC7A5 \uD3B8\uC548\uD569\uB2C8\uB2E4.",
