  "settings": "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438",
  "theme-font-text-size-column-count-and-the-jump-back-block-a-list": "\u0422\u0435\u043C\u0430, \u0448\u0440\u0438\u0444\u0442, \u0440\u0430\u0437\u043C\u0435\u0440 \u0442\u0435\u043A\u0441\u0442\u0430, \u0447\u0438\u0441\u043B\u043E \u043A\u043E\u043B\u043E\u043D\u043E\u043A \u0438 \u0431\u043B\u043E\u043A \xAB\u0412\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u043A \u043C\u0435\u0441\u0442\u0443\xBB \u2014 \u0441\u043F\u0438\u0441\u043E\u043A \u0442\u043E\u0447\u0435\u043A, \u043A \u043A\u043E\u0442\u043E\u0440\u044B\u043C \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u043A\u0430\u0442\u0438\u0442\u044C\u0441\u044F.",
