// src/original/i18n-runtime.js
var HAN = /[\u3400-\u9fff]/;
var CYRILLIC = /[А-Яа-яЁё]/;
function isChineseSourceText(value) {
  const text4 = String(value || "");
  return HAN.test(text4) && !CYRILLIC.test(text4);
}
function translateUiText(language, source, english, chinese) {
  const text4 = String(source ?? "");
  if (language === "zh") return chinese?.[text4] ?? text4;
  if (language === "en") return english?.[text4] ?? text4;
  if (language === "ru") {
    const russian = UI_TRANSLATIONS.ru?.[text4];
    if (typeof russian === "string" && russian) return russian;
    if (isChineseSourceText(text4)) return english?.[text4] ?? text4;
    return text4;
  }
  return UI_TRANSLATIONS[language]?.[text4] || english?.[text4] || text4;
}

